const pdfDialog=el('dialog',{class:'pdf-dialog','aria-labelledby':'pdf-title'});pdfDialog.innerHTML='<h2 id="pdf-title">Print or save your report</h2><p>The PDF includes every sheet, cutting sizes, and edge banding in metres.</p><p id="pdf-help">On iPhone, choose Share PDF, then Print or Save to Files.</p><div class="pdf-actions"><button id="share-pdf">Share PDF</button><button id="save-pdf">Save PDF</button><button id="browser-print">Print in browser</button><button id="close-pdf">Close</button></div><p id="pdf-message" role="status"></p>';document.body.append(pdfDialog);
function reportDocument(){return ReportPDF.createReportPDF(window.jspdf.jsPDF,state,result);}
function reportFile(){return new File([reportDocument().output('blob')],'sheetwise-report.pdf',{type:'application/pdf'});}
$('print').onclick=()=>{if(dirty&&!run())return;if(!result?.sheets.length){$('error').textContent='Add parts and optimize a layout before printing.';return;}buildReport();$('pdf-message').textContent='';const fileSharing=!!navigator.canShare&&navigator.canShare({files:[new File([''],'report.pdf',{type:'application/pdf'})]});$('share-pdf').hidden=!fileSharing;$('pdf-help').textContent=fileSharing?'On iPhone, choose Share PDF, then Print or Save to Files.':'Save the PDF, then open it in your PDF viewer to print.';const ios=/iPad|iPhone|iPod/.test(navigator.userAgent)||(navigator.platform==='MacIntel'&&navigator.maxTouchPoints>1);$('browser-print').hidden=ios&&(navigator.standalone||matchMedia('(display-mode: standalone)').matches);pdfDialog.showModal();};
$('share-pdf').onclick=()=>{try{const file=reportFile();navigator.share({files:[file],title:'Sheetwise cutting report'}).catch(error=>{if(error.name!=='AbortError')$('pdf-message').textContent='Sharing was unavailable. Use Save PDF instead.';});}catch{$('pdf-message').textContent='Could not prepare the PDF. Please try Save PDF.';}};
$('save-pdf').onclick=()=>{try{reportDocument().save('sheetwise-report.pdf');$('pdf-message').textContent='PDF ready. Open the saved file and use Share to print.';}catch{$('pdf-message').textContent='Could not create the PDF. Please try again.';}};
$('browser-print').onclick=()=>{pdfDialog.close();buildReport();window.print();};$('close-pdf').onclick=()=>pdfDialog.close();
